import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)

def get_versions(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-2] if proj['path'].endswith('.csproj') else proj['path']
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (name, pkg['id'])
                result[key] = pkg.get('resolvedVersion', pkg.get('requestedVersion','?'))
    return result

bv = get_versions(b)
av = get_versions(a)
print('=== CHANGES ===')
for k in sorted(set(list(bv.keys()) + list(av.keys()))):
    bver = bv.get(k, 'MISSING')
    aver = av.get(k, 'MISSING')
    if bver != aver:
        print(f'  {k[0]}/{k[1]}: {bver} -> {aver}')
print('=== UNCHANGED ===')
for k in sorted(bv.keys()):
    if bv.get(k) == av.get(k):
        print(f'  {k[0]}/{k[1]}: {bv[k]}')
" 2>&1 | head -40

